package com.turboio.tools;
import java.io.*;import java.util.*;import java.util.zip.*;import java.security.*;import org.json.*;
/** Read-only, shell-UID audit of one named phone export; never returns sound. */
public final class VerifyAudioExport {
 static void check(boolean b)throws IOException{if(!b)throw new IOException("EXPORT_AUDIT_FAILED");}
 static long le(byte[] b,int p,int n){long v=0;for(int i=0;i<n;i++)v|=(b[p+i]&255L)<<(8*i);return v;}
 static long ogg(byte[] b)throws IOException{int at=0,sequence=0;long serial=-1,packets=0;boolean eos=false;while(at<b.length){check(at+27<=b.length&&b[at]=='O'&&b[at+1]=='g'&&b[at+2]=='g'&&b[at+3]=='S'&&b[at+4]==0&&!eos);int n=b[at+26]&255,len=27+n;check(at+len<=b.length);for(int i=0;i<n;i++){int lace=b[at+27+i]&255;len+=lace;if(lace<255)packets++;}check(at+len<=b.length);long pageSerial=le(b,at+14,4);if(serial<0){serial=pageSerial;check((b[at+5]&2)!=0&&len>=27+n+8&&new String(b,at+27+n,8,java.nio.charset.StandardCharsets.US_ASCII).equals("OpusHead"));}check(serial==pageSerial&&le(b,at+18,4)==sequence++);int crc=0;for(int i=0;i<len;i++){int v=i>=22&&i<26?0:b[at+i]&255;crc^=v<<24;for(int bit=0;bit<8;bit++)crc=(crc<<1)^((crc<0)?0x04c11db7:0);}check((crc&0xffffffffL)==le(b,at+22,4));eos=(b[at+5]&4)!=0;at+=len;}check(eos&&packets>2);return packets-2;}
 public static void main(String[] a)throws Exception{
  check(a.length==2&&a[0].matches("/sdcard/Download/io-agent-audio-export-[0-9]{8}-codex-[a-f0-9]{6}\\.zip")&&a[1].matches("[a-f0-9]{64}"));File file=new File(a[0]);check(file.isFile()&&file.length()>0&&file.length()<=67108864);MessageDigest digest=MessageDigest.getInstance("SHA-256");try(InputStream in=new FileInputStream(file)){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;)digest.update(b,0,n);}StringBuilder hash=new StringBuilder();for(byte v:digest.digest())hash.append(String.format(Locale.ROOT,"%02x",v&255));check(hash.toString().equals(a[1]));
  Map<String,Long> frames=new HashMap<>();JSONObject index=null;int entries=0;long total=0;try(ZipFile zip=new ZipFile(file)){Enumeration<? extends ZipEntry> items=zip.entries();Set<String> names=new HashSet<>();while(items.hasMoreElements()){ZipEntry e=items.nextElement();check(++entries<=258&&!e.isDirectory()&&names.add(e.getName())&&!e.getName().contains("..")&&e.getSize()>=0&&e.getSize()<=16777216&&(total+=e.getSize())<=67108864);byte[] bytes;try(InputStream in=zip.getInputStream(e);ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];for(int n;(n=in.read(b))!=-1;){check(out.size()+n<=e.getSize());out.write(b,0,n);}bytes=out.toByteArray();}try{CRC32 crc=new CRC32();crc.update(bytes);check(bytes.length==e.getSize()&&crc.getValue()==e.getCrc());if(e.getName().endsWith(".opus"))frames.put(e.getName(),ogg(bytes));else if(e.getName().equals("片段索引.json")){check(bytes.length<=262144);index=new JSONObject(new String(bytes,java.nio.charset.StandardCharsets.UTF_8));}else check(e.getName().equals("说明.txt"));}finally{Arrays.fill(bytes,(byte)0);}}}
  check(index!=null&&index.getBoolean("remote_stored")&&index.getBoolean("export_uses_remote")&&index.getBoolean("source_link_verified")&&!index.getBoolean("recording_complete"));JSONArray parts=index.getJSONArray("parts");check(parts.length()>0&&parts.length()==frames.size()&&entries==parts.length()+2);long count=0;Set<String> linked=new HashSet<>();for(int i=0;i<parts.length();i++){JSONObject part=parts.getJSONObject(i);String name=part.getString("file");check(linked.add(name)&&frames.containsKey(name)&&frames.get(name)==part.getLong("frames")&&!part.getBoolean("recording_complete"));JSONArray origins=part.getJSONArray("origins");check(origins.length()>0);for(int j=0;j<origins.length();j++)check("server".equals(origins.getJSONObject(j).getString("location")));count+=frames.get(name);}
  System.out.println(new JSONObject().put("passed",true).put("bytes",file.length()).put("sha256",hash.toString()).put("zip_entries",entries).put("opus_parts",parts.length()).put("audio_packets",count).put("zip_crc_verified",true).put("ogg_page_crc_sequence_and_packet_counts_verified",true).put("remote_only_origins",true).put("recording_complete",false).put("audio_bytes_returned",false).toString());
 }
}
